from collections import Counter

def transform(grid):
    H, W = len(grid), len(grid[0])
    sep_rows = [r for r in range(H) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(W) if len({grid[r][c] for r in range(H)}) == 1]
    sep = grid[sep_rows[0]][0] if sep_rows else grid[0][sep_cols[0]]
    # row bands
    rb = []
    prev = 0
    for r in sep_rows + [H]:
        if r > prev: rb.append((prev, r))
        prev = r + 1
    cb = []
    prev = 0
    for c in sep_cols + [W]:
        if c > prev: cb.append((prev, c))
        prev = c + 1
    # background = most common non-separator color
    cnt = Counter(v for row in grid for v in row if v != sep)
    bg = cnt.most_common(1)[0][0]
    out = []
    for r0, r1 in rb:
        row = []
        for c0, c1 in cb:
            vals = {grid[r][c] for r in range(r0, r1) for c in range(c0, c1)}
            anom = vals - {sep, bg}
            row.append(1 if anom else bg)
        out.append(row)
    return out
