from collections import Counter

def transform(grid):
    H, W = len(grid), len(grid[0])
    sep_rows = [r for r in range(H) if all(grid[r][c] == grid[r][0] for c in range(W))]
    sep_cols = [c for c in range(W) if all(grid[r][c] == grid[0][c] for r in range(H))]
    if sep_rows:
        sep = grid[sep_rows[0]][0]
    elif sep_cols:
        sep = grid[0][sep_cols[0]]
    else:
        sep = None
    rowbands = []
    prev = 0
    for r in sep_rows + [H]:
        if r > prev:
            rowbands.append((prev, r))
        prev = r + 1
    colbands = []
    prev = 0
    for c in sep_cols + [W]:
        if c > prev:
            colbands.append((prev, c))
        prev = c + 1
    cnt = Counter(v for row in grid for v in row if v != sep)
    bg = cnt.most_common(1)[0][0]
    out = []
    for r0, r1 in rowbands:
        rowout = []
        for c0, c1 in colbands:
            n = sum(1 for r in range(r0, r1) for c in range(c0, c1)
                    if grid[r][c] != sep and grid[r][c] != bg)
            rowout.append(1 if n >= 2 else bg)
        out.append(rowout)
    return out
